From 99a7b54b77bc11efde1f5ede67f2311161b2977d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:11:37 +0100
Subject: [PATCH] klipper: keep only the final selection of a drag in history

GTK apps and Chromium update the primary selection on every step of a
drag, so each partial selection got its own entry. A selection extending
or shrinking the one saved less than a second earlier now replaces it.

BUG: 498894
---
 klipper/historymodel.cpp | 29 ++++++++++++++++++++++++++++-
 klipper/historymodel.h   |  4 ++++
 2 files changed, 32 insertions(+), 1 deletion(-)

diff --git a/klipper/historymodel.cpp b/klipper/historymodel.cpp
index 8112dadb5b..3410655907 100644
--- a/klipper/historymodel.cpp
+++ b/klipper/historymodel.cpp
@@ -826,9 +826,13 @@ bool HistoryModel::insert(const QMimeData *mimeData, qreal timestamp)
     }

     ++m_pendingJobs;
-    connect(updateJob, &KJob::finished, this, [this] {
+    connect(updateJob, &KJob::finished, this, [this, updateJob] {
         --m_pendingJobs;
+        if (m_lastUpdateJob == updateJob) {
+            m_lastUpdateJob.clear();
+        }
     });
+    m_lastUpdateJob = updateJob;
     updateJob->start();

     return true;
@@ -1081,7 +1085,30 @@ void HistoryModel::checkClipData(QClipboard::Mode mode, const QMimeData *data)
         return;
     }

+    const HistoryItemConstPtr previousTop = first();
+    const QPointer<UpdateDatabaseJob> previousUpdateJob = m_lastUpdateJob;
     if (insert(data)) [[likely]] {
+        // Some clients update the selection on every step of a drag; keep only the latest one
+        if (selectionMode && previousTop && previousTop->uuid() == m_lastSelectionUuid && m_lastSelectionTimer.durationElapsed() < 1s && m_items.size() > 1
+            && m_items[1] == previousTop && !isItemStarred(previousTop->uuid())) {
+            const QString oldText = previousTop->text();
+            const QString newText = m_items[0]->text();
+            if (!oldText.isEmpty() && !newText.isEmpty()
+                && (newText.startsWith(oldText) || newText.endsWith(oldText) || oldText.startsWith(newText) || oldText.endsWith(newText))) {
+                auto removePrevious = [this, uuid = previousTop->uuid()] {
+                    if (const int row = indexOf(uuid); row > 0) {
+                        removeRow(row);
+                    }
+                };
+                if (previousUpdateJob) {
+                    connect(previousUpdateJob, &KJob::finished, this, removePrevious);
+                } else {
+                    removePrevious();
+                }
+            }
+        }
+        m_lastSelectionUuid = selectionMode ? m_items[0]->uuid() : QString();
+        m_lastSelectionTimer.start();
         qCDebug(KLIPPER_LOG) << "Synchronize?" << m_bSynchronize;
         if (m_bSynchronize) { // applyClipChanges can return nullptr
             m_clip->setMimeData(data,
diff --git a/klipper/historymodel.h b/klipper/historymodel.h
index 15fe0f0f68..8d8e4f02af 100644
--- a/klipper/historymodel.h
+++ b/klipper/historymodel.h
@@ -11,6 +11,7 @@
 #include <QBindable>
 #include <QClipboard>
 #include <QDateTime>
+#include <QElapsedTimer>
 #include <QPointer>
 #include <QSqlDatabase>

@@ -178,6 +179,9 @@ private:
     bool m_bActionOnSelection = true;
     bool m_clipboardHasPassword = false;
     bool m_selectionHasPassword = false;
+    QString m_lastSelectionUuid;
+    QElapsedTimer m_lastSelectionTimer;
+    QPointer<UpdateDatabaseJob> m_lastUpdateJob;

     friend class DeclarativeHistoryModel;
     friend class HistoryModelTest;
